def _revive(obj):
    """json.loads `object_hook`: rebuild a value that _mark described."""
    if TYPE_KEY not in obj:
        return obj
    module_name, _, name = obj[TYPE_KEY].rpartition(".")
    # Only allow imports from the 'datetime' and 'decimal' modules to prevent arbitrary code execution.
    allowed_modules = {"datetime", "decimal"}
    if module_name not in allowed_modules:
        raise MessageError(f"unauthorized module: {module_name}")
    factory = getattr(importlib.import_module(module_name), name)
    return factory(*obj.get("args", []))

def post_login_redirect(next_url, site_host, default=DEFAULT_LANDING):
    """Where to send the browser after a successful login.

    `next_url` is the ?next= parameter of the login page. Only targets on this site are
    followed: site-relative paths and absolute https URLs on `site_host`. Anything else
    falls back to `default`.
    """
    if not next_url:
